/**
 * Title Page (Shaar Blat) — live SVG preview of one stock border style.
 * (v0.5.0 — Title Page builder)
 *
 * The geometry comes from the borders engine (`buildTitlePageBorderCommands`)
 * — the same commands the PDF exporter draws — so the thumbnail is a true
 * miniature of the printed frame. The markup is generated by our own
 * engine (no user text), so innerHTML is safe here.
 */

import React, { useMemo } from 'react';
import {
  borderCommandsToSvg,
  buildTitlePageBorderCommands,
} from '../engine/title-page-borders';
import type { TitlePageBorderStyleId } from '../types/design-settings';

interface TitlePageBorderPreviewProps {
  styleId: TitlePageBorderStyleId;
  thicknessPt?: number;
  insetMm?: number;
  className?: string;
}

export const TitlePageBorderPreview: React.FC<TitlePageBorderPreviewProps> = ({
  styleId,
  thicknessPt = 1,
  insetMm = 12,
  className,
}) => {
  const svg = useMemo(() => {
    if (styleId === 'none') return '';
    const commands = buildTitlePageBorderCommands(styleId, insetMm, thicknessPt, 482, 680);
    // Stroke width in normalized units (page height 680pt maps to 1000).
    const strokeW = Math.max(1.5, (thicknessPt * 1000) / 680);
    return borderCommandsToSvg(commands, '#3a352e', strokeW);
  }, [styleId, thicknessPt, insetMm]);

  if (styleId === 'none') {
    return (
      <div
        className={className}
        style={{ border: '1px dashed #c9c2b4', background: '#fffdf8', boxSizing: 'border-box' }}
      />
    );
  }
  return (
    <svg
      viewBox="0 0 1000 1000"
      preserveAspectRatio="none"
      className={className}
      style={{ background: '#fffdf8', display: 'block' }}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
};
